import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

/**
 * Fix: Refactored to follow @google/genai best practices:
 * 1. Uses named parameter in GoogleGenAI constructor.
 * 2. Uses process.env.API_KEY directly.
 * 3. Uses recommended { parts: [...] } structure for contents.
 * 4. Accesses .text as a property.
 */
export async function transcribeAudio(audioBlob: Blob): Promise<string> {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY_NOT_FOUND");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const base64Data = await blobToBase64(audioBlob);

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        {
          inlineData: {
            mimeType: 'audio/wav',
            data: base64Data
          }
        },
        {
          text: "Precisely transcribe this audio. Return only the transcription text. No metadata, no speakers labels, just the words spoken."
        }
      ]
    },
  });

  return response.text || "[EMPTY_TRANSCRIPTION]";
}

function blobToBase64(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

