import React, { useState, useRef, useEffect } from 'react';
import { Upload, FileAudio, Zap, PlayCircle, Loader2, X, Download, Copy, CheckCircle2, FileText, Settings } from 'lucide-react';
import WaveformPreview from './components/WaveformPreview';
import TerminalOutput from './components/TerminalOutput';
import { AppStatus, SystemLog, ProcessingSegment } from './types';
import { sliceAudioBuffer } from './services/wavEncoder';
import { transcribeAudio } from './services/geminiService';

const SEGMENT_THRESHOLD = 270; // 4 minutes 30 seconds
const BUFFER_MIN_DURATION = 5; // 5 seconds buffer rule

const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [file, setFile] = useState<File | null>(null);
  const [audioBuffer, setAudioBuffer] = useState<AudioBuffer | null>(null);
  const [logs, setLogs] = useState<SystemLog[]>([]);
  const [transcript, setTranscript] = useState<string>('');
  const [copyFeedback, setCopyFeedback] = useState(false);
  const [isSrtMode, setIsSrtMode] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  const addLog = (message: string, type: SystemLog['type'] = 'INFO') => {
    const newLog: SystemLog = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      message,
      type
    };
    setLogs(prev => [...prev, newLog]);
  };

  /**
   * Finalization Step: Global SRT Re-indexing
   * Splits the master string into lines and re-labels every SRT block index 
   * sequentially from 1 to N, ignoring reset indexes from separate AI chunks.
   */
  const reindexSRT = (rawString: string): string => {
    const lines = rawString.replace(/\r\n/g, '\n').split('\n');
    let counter = 1;
    const resultLines: string[] = [];

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      const nextLine = lines[i + 1]?.trim() || '';

      // Match digit-only lines that strictly precede a valid SRT timestamp pattern
      const isIndexCandidate = /^\d+$/.test(line);
      const isTimestampNext = /\d{2}:\d{2}:\d{2},\d{3} --> \d{2}:\d{2}:\d{2},\d{3}/.test(nextLine);

      if (isIndexCandidate && isTimestampNext) {
        resultLines.push((counter++).toString());
      } else {
        resultLines.push(lines[i]);
      }
    }

    return resultLines.join('\n');
  };

  const initAudioContext = () => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioContextRef.current;
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFile = e.target.files?.[0];
    if (!selectedFile) return;

    resetApp();
    setFile(selectedFile);
    setStatus(AppStatus.LOADING);
    addLog(`INITIALIZING_FILE_CAPTURE: ${selectedFile.name}`);

    const context = initAudioContext();
    try {
      const arrayBuffer = await selectedFile.arrayBuffer();
      const decoded = await context.decodeAudioData(arrayBuffer);
      setAudioBuffer(decoded);
      setStatus(AppStatus.READY);
      addLog(`SIGNAL_STABILIZED: ${decoded.duration.toFixed(2)}s DETECTED`, 'SUCCESS');
    } catch (error) {
      addLog(`SIGNAL_DECODE_FAILURE: UNRECOGNIZED_FORMAT`, 'ERROR');
      setStatus(AppStatus.ERROR);
    }
  };

  const resetApp = () => {
    setFile(null);
    setAudioBuffer(null);
    setLogs([]);
    setTranscript('');
    setStatus(AppStatus.IDLE);
    setCopyFeedback(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const startProcessing = async () => {
    if (!audioBuffer || !file) return;

    setStatus(AppStatus.PROCESSING);
    setTranscript('');
    addLog(`INITIATING_LINEAR_OPTIMIZATION_PROTOCOL`, 'PROCESS');
    addLog(`ENCODER_TARGET: ${isSrtMode ? 'SUBRIP_SRT_FORMAT' : 'STANDARD_PLAINTEXT'}`, 'INFO');

    const duration = audioBuffer.duration;
    const segments: { start: number; end: number }[] = [];

    let current = 0;
    while (current < duration) {
      let end = current + SEGMENT_THRESHOLD;
      let remaining = duration - end;

      if (remaining < BUFFER_MIN_DURATION) {
        end = duration;
      }

      segments.push({ start: current, end: end });
      current = end;
    }

    addLog(`SEGMENTATION_COMPLETE: ${segments.length} PROCESSING_UNITS_IDENTIFIED`, 'INFO');

    const context = initAudioContext();
    let finalTranscript = '';

    try {
      for (let i = 0; i < segments.length; i++) {
        const seg = segments[i];
        const timeOffset = seg.start;

        addLog(`PROCESSING_UNIT_${i + 1}/${segments.length} [START: ${timeOffset.toFixed(1)}s]`, 'PROCESS');

        const blob = sliceAudioBuffer(audioBuffer, seg.start, seg.end, context);
        const result = await transcribeAudio(blob, isSrtMode, timeOffset);

        // Append result to local buffer
        // Note: For SRT we add spacing between chunked AI outputs to aid reindexing
        finalTranscript += (finalTranscript ? '\n\n' : '') + result.trim();
        setTranscript(finalTranscript);
        addLog(`UNIT_${i + 1}_DECRYPTED`, 'SUCCESS');
      }

      // Finalization Step for SRT
      if (isSrtMode) {
        addLog(`FINALIZING_TEMPORAL_SEQUENCE: REINDEXING_SRT_BLOCKS`, 'PROCESS');
        const indexedTranscript = reindexSRT(finalTranscript);
        setTranscript(indexedTranscript);
      }

      setStatus(AppStatus.COMPLETED);
      addLog(`PROTOCOL_TERMINATED: ALL_DATA_SEQUENCED`, 'SUCCESS');
    } catch (error: any) {
      const msg = error.message === 'API_KEY_NOT_FOUND' ? 'API_KEY_MISSING' : 'NEURAL_LINK_ERROR';
      addLog(`CRITICAL_ERROR: ${msg}`, 'ERROR');
      setStatus(AppStatus.ERROR);
    }
  };

  const downloadTranscript = () => {
    const extension = isSrtMode ? 'srt' : 'txt';
    const mimeType = isSrtMode ? 'text/srt' : 'text/plain';
    const blob = new Blob([transcript], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${isSrtMode ? 'SUBTITLES' : 'TRANSCRIPT'}_${file?.name.split('.')[0] || 'OUTPUT'}.${extension}`;
    a.click();
    URL.revokeObjectURL(url);
    addLog(`DATA_EXPORTED: .${extension.toUpperCase()}_FILE_READY`, "SUCCESS");
  };

  const copyToClipboard = () => {
    if (!transcript) return;
    navigator.clipboard.writeText(transcript);
    setCopyFeedback(true);
    addLog("TRANSCRIPT_COPIED_TO_LOCAL_BUFFER", "SUCCESS");
    setTimeout(() => setCopyFeedback(false), 2000);
  };

  return (
    <div className="min-h-screen bg-[#09090b] text-zinc-300 font-sans selection:bg-cyan-500 selection:text-black flex flex-col">
      <header className="border-b border-zinc-800 bg-zinc-950/80 backdrop-blur sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-4 h-14 bg-cyan-500 shadow-[0_0_20px_rgba(6,182,212,0.6)] rounded-sm"></div>
            <div>
              <h1 className="text-2xl font-mono font-bold tracking-[0.3em] text-white flex items-center gap-3">
                TERMINAL-U <span className="text-zinc-700">//</span> TRANSCRIBER
              </h1>
              <p className="font-mono text-[9px] text-zinc-500 tracking-[0.5em] uppercase mt-1">
                Linear_Audio_Optimization_System_v2.0
              </p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <div className="flex flex-col items-end">
              <span className="font-mono text-[10px] text-zinc-500 uppercase">System_State</span>
              <span className={`font-mono text-xs font-bold uppercase ${
                status === AppStatus.PROCESSING ? 'text-cyan-400 animate-pulse' :
                status === AppStatus.COMPLETED ? 'text-green-500' :
                status === AppStatus.ERROR ? 'text-red-500' : 'text-zinc-400'
              }`}>
                {status}
              </span>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl mx-auto w-full p-8 grid grid-cols-1 lg:grid-cols-5 gap-8 overflow-hidden">
        <div className="lg:col-span-2 flex flex-col gap-6">
          <div className="bg-zinc-900/40 border border-zinc-800 rounded-2xl p-8 flex flex-col gap-8 shadow-xl relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <FileAudio size={120} />
            </div>

            <div className="flex flex-col gap-2">
              <h2 className="font-mono text-[10px] text-cyan-500 uppercase tracking-widest font-bold flex items-center gap-2">
                <Settings size={12} />
                01. Ingestion_Protocol
              </h2>
              <p className="text-zinc-500 text-xs">Load audio source and select encoder target.</p>
            </div>

            <div className="flex flex-col gap-4 bg-zinc-950/50 p-4 rounded-xl border border-zinc-800/50">
              <div className="flex items-center justify-between">
                <div className="flex flex-col">
                  <span className="font-mono text-[10px] text-white font-bold uppercase tracking-wider">YT_SRT_ENCODER</span>
                  <span className="text-[9px] text-zinc-600 uppercase">YouTube Compatible Subtitles</span>
                </div>
                <button 
                  onClick={() => setIsSrtMode(!isSrtMode)}
                  disabled={status === AppStatus.PROCESSING}
                  className={`w-12 h-6 rounded-full transition-all relative ${isSrtMode ? 'bg-cyan-500 shadow-[0_0_15px_rgba(6,182,212,0.4)]' : 'bg-zinc-800'} ${status === AppStatus.PROCESSING ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
